   460→  /** Manually refresh the room list and update the atom */
   461→  public static refreshRoomList = async () => {
   462→    if (!this.instance) return;
   463→
   464→    try {
   465→      const roomsArray = this.getRooms();
   466→
   467→      const sortedRooms = await Promise.all(
   468→        roomsArray.map(async (room) => ({
   469→          room,
   470→          timestamp: (await room.latestEvent())?.timestamp || 0,
   471→        })),
   472→      );
   473→
   474→      const filteredAndSortedRooms = sortedRooms
   475→        .filter(({ room }) => {
   476→          const membership = room.membership();
   477→
   478→          return (
   479→            membership !== Membership.Banned &&
   480→            membership !== Membership.Left &&
   481→            membership !== Membership.Knocked
   482→          );
   483→        })
   484→        .sort((a, b) => {
   485→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
   486→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
   487→          if (aInvited !== bInvited) return bInvited - aInvited;
   488→
   489→          return Number(b.timestamp) - Number(a.timestamp);
   490→        });
   491→
   492→      MatrixJotaiStore.set(
   493→        MatrixAtoms.roomList,
   494→        filteredAndSortedRooms.map(({ room }) => room),
   495→      );
   496→    } catch (error) {
   497→      console.error("Failed to refresh room list:", error);
   498→    }
   499→  };
