   541→  /** Deactivate the user's account permanently
   542→   * Warning: This is irreversible and will delete all user data */
   543→  public static deactivateAccount = async (password: string) => {
   544→    if (!this.instance) throw new Error("Client not initialized");
   545→
   546→    try {
   547→      // First request with undefined auth_data (will always fail per UIA spec)
   548→      try {
   549→        await this.instance.deactivateAccount(undefined, true);
   550→      } catch {
   551→        // Expected to fail
   552→      }
   553→
   554→      console.log(this.instance.userId(), "userId");
   555→      const userId = this.instance.userId();
   556→      if (!userId) throw new Error("User ID not found");
   557→
   558→      const authData = new AuthData.Password({
   559→        passwordDetails: AuthDataPasswordDetails.create({
   560→          identifier: userId,
   561→          password,
   562→        }),
   563→      });
   564→
   565→      // Step 4: Second request with auth data
   566→      await this.instance.deactivateAccount(authData, true);
   567→
   568→      // After successful deactivation, clean up local data
   569→      await this.logout();
   570→    } catch (error) {
   571→      console.error("Failed to deactivate account:", error);
   572→      throw error;
   573→    }
   574→  };
