  1081→  public static getReadReceipts = async (event: EventTimelineItem) => {
  1082→    const userIds = Array.from(event.readReceipts.keys()).map(
  1083→      (userIds) => userIds,
  1084→    );
  1085→
  1086→    // Don't show read receipts for the sender's own message
  1087→    const filteredUserIds = userIds.filter((userId) => userId !== event.sender);
  1088→
  1089→    if (!filteredUserIds.length) {
  1090→      return [];
  1091→    }
  1092→
  1093→    try {
  1094→      const profilePromises = filteredUserIds.map((userId) =>
  1095→        this.instance?.getProfile(userId),
  1096→      );
  1097→      const profiles = await Promise.allSettled(profilePromises);
  1098→      return profiles
  1099→        .filter((p) => p.status === "fulfilled")
  1100→        .map((p) => p.value)
  1101→        .filter((p) => p !== undefined);
  1102→    } catch (error) {
  1103→      console.error("Failed to get read receipt users:", error);
  1104→      return [];
  1105→    }
  1106→  };
