  1467→          this.onVerificationStateChange?.("emojis");
  1468→          this.onVerificationEmojis?.(emojis);
  1469→        } else if (data.tag === SessionVerificationData_Tags.Decimals) {
  1470→          console.log("🔢 Decimals:", data.inner.values);
