  1486→        this.onVerificationStateChange?.("success");
  1487→      },
  1488→    };
  1489→
  1490→    // Set the delegate
  1491→    this.verificationController.setDelegate(delegate);
  1492→    console.log("✅ Verification controller set up successfully");
