  1834→    roomId: string,
  1835→    eventId: string,
  1836→  ): Promise<void> => {
  1837→    if (!this.instance) throw new Error("Client not initialized");
  1838→
  1839→    const room = this.instance.getRoom(roomId);
  1840→    if (!room) throw new Error("Room not found");
  1841→
  1842→    const timeline = await room.timeline();
  1843→    if (!timeline) throw new Error("Timeline not found");
