    23→/** Get the current user ID, works in both foreground and background */
    24→const getCurrentUserId = (): string | null => {
    25→  // Try to get from active instance first (foreground)
    26→  const instanceUserId = MatrixService.instance?.userId();
    27→  if (instanceUserId) return instanceUserId;
    28→
    29→  // Fall back to stored credentials (works in background)
    30→  const credentials = MatrixStorage.getLoginCredentials();
    31→  return credentials?.userId || null;
    32→};
    33→
    34→/**
    35→ * Ensure MatrixService is initialized for background decryption
    36→ * Uses lightweight initialization that doesn't start sync service
    37→ */
    38→const ensureServiceInitialized = async (): Promise<boolean> => {
    39→  const notificationClient = MatrixService.getNotificationClient();
    40→  if (notificationClient) return true;
    41→
    42→  // Foreground: create notification client if possible
    43→  if (MatrixService.instance) {
    44→    const client = await MatrixService.ensureNotificationClient();
    45→    return !!client;
    46→  }
    47→
    48→  // Try to restore session with lightweight background method
    49→  try {
    50→    const restored = await MatrixService.restoreSessionForBackground();
    51→    return restored;
    52→  } catch (error) {
    53→    console.error("[Push] Failed to restore session:", error);
    54→    return false;
    55→  }
    56→};
    57→
    58→const handleReceivedMessage = async (
    59→  message: FirebaseMessagingTypes.RemoteMessage,
    60→) => {
    61→  const data = message.data as unknown as NotificationData;
    62→  if (!data) return;
    63→
    64→  // Skip notifications for own messages (works in both foreground and background)
    65→  const currentUserId = getCurrentUserId();
    66→  if (currentUserId && data.sender === currentUserId) return;
    67→
    68→  const isCallOnIOS =
    69→    Platform.OS === "ios" &&
    70→    (data.type === "m.call.invite" || data.type === "m.call.member");
    71→
    72→  if (isCallOnIOS) {
    73→    // Skip if sync-based detection already triggered CallKit for this room
    74→    if (CallKitService.isRingingForRoom(data.room_id)) return;
    75→
    76→    CallKitService.displayIncomingCall({
    77→      roomId: data.room_id,
    78→      roomName: data.room_name || data.sender_display_name || data.sender,
    79→      senderDisplayName: data.sender_display_name || data.sender,
    80→    });
    81→    return;
    82→  }
    83→
    84→  const notificationId = message.messageId || `msg_${Date.now()}`;
    85→  const formattedMessage = formatLocalPushNotificationMessage(data);
    86→
    87→  if (!formattedMessage) return;
    88→
    89→  // Decrypt encrypted messages, then check if it's a call or a regular message
    90→  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
    91→    try {
    92→      // Always ensure service is initialized for encrypted messages
    93→      const initialized = await ensureServiceInitialized();
    94→      if (!initialized) return;
    95→
    96→      // Check if the decrypted event is a call — route to CallKit on iOS
    97→      if (Platform.OS === "ios") {
    98→        const isCall = await isDecryptedEventCall(data.room_id, data.event_id);
    99→
   100→        if (isCall) {
   101→          // Skip if sync-based detection already triggered CallKit for this room
   102→          if (CallKitService.isRingingForRoom(data.room_id)) return;
   103→
   104→          const roomName = MatrixService.getRoomInfo(
   105→            data.room_id,
   106→          )?.displayName();
   107→
   108→          CallKitService.displayIncomingCall({
   109→            roomId: data.room_id,
   110→            roomName:
   111→              roomName ||
   112→              data.room_name ||
   113→              data.sender_display_name ||
   114→              data.sender,
   115→            senderDisplayName: data.sender_display_name || data.sender,
   116→          });
   117→          return;
   118→        }
   119→      }
   120→
   121→      const roomName = MatrixService.getRoomInfo(data.room_id)?.displayName();
   122→      const decryptedContent = await getDecryptedEventContent(
   123→        data.room_id,
   124→        data.event_id,
   125→      );
   126→
   127→      if (decryptedContent) {
   128→        await NotifeeService.create({
   129→          title:
   130→            roomName ||
   131→            data.room_name ||
   132→            data.sender_display_name ||
   133→            data.sender ||
   134→            "Unknown Sender",
   135→          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
   136→          id: notificationId,
   137→          data: { room_id: data.room_id },
   138→        });
   139→      } else {
   140→        await NotifeeService.create({
   141→          title: formattedMessage.title,
   142→          message: formattedMessage.message,
   143→          id: notificationId,
   144→          data: { room_id: formattedMessage.room_id },
   145→        });
   146→      }
   147→    } catch (error) {
   148→      console.error("[Push] Failed to decrypt:", error);
   149→    }
   150→
   151→    return;
   152→  }
   153→
   154→  // For non-encrypted messages, show directly
   155→  await NotifeeService.create({
   156→    title: formattedMessage.title,
   157→    message: formattedMessage.message,
   158→    id: notificationId,
   159→    data: { room_id: formattedMessage.room_id },
   160→  });
   161→};
