   163→export const PushNotificationsService = {
   164→  getToken: async () => await getToken(getMessaging()),
   165→  /** Register the device with Matrix homeserver for push notifications
   166→   * This should be called after successful login and after push permissions */
   167→  registerPusher: async () => {
   168→    try {
   169→      const fcmToken = await getToken(getMessaging());
   170→      await MatrixService.setPusher(fcmToken);
   171→      return true;
   172→    } catch (error) {
   173→      console.error("Failed to register push notifications:", error);
   174→      throw error;
   175→    }
   176→  },
   177→  /** Unregister the device from Matrix homeserver */
   178→  unregisterPusher: async () => {
   179→    try {
   180→      const fcmToken = await getMessaging().getToken();
   181→      await MatrixService.removePusher(fcmToken);
   182→      return true;
   183→    } catch (error) {
   184→      console.error("Failed to unregister push notifications:", error);
   185→      throw error;
   186→    }
   187→  },
   188→  registerListeners: async () => {
   189→    // Foreground message handler
   190→    onMessage(getMessaging(), async (message) => {
   191→      await handleReceivedMessage(message);
   192→    });
   193→  },
   194→  /** Handle background messages - called from index.js */
   195→  handleBackgroundMessage: async (
   196→    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
   197→  ) => {
   198→    await handleReceivedMessage(remoteMessage);
   199→  },
   200→  checkPermissions: async () => {
   201→    const result = await checkNotifications();
   202→    return result.status === RESULTS.GRANTED;
   203→  },
   204→  requestPermissions: async () => {
   205→    const result = await requestNotifications(["alert"]);
   206→    return result.status === RESULTS.GRANTED;
   207→  },
   208→  subscribeToTopic: async (topic: string) => {
   209→    await getMessaging().subscribeToTopic(topic);
   210→  },
   211→  unsubscribeFromTopic: async (topic: string) => {
   212→    await getMessaging().unsubscribeFromTopic(topic);
   213→  },
   214→};
